Stack<Integer> stack = new Stack<>();
Stack<Integer> minStack = new Stack<>();

void push(int val) {
    stack.push(val);
    if (minStack.isEmpty()) {
        minStack.push(val);
    } else {
        minStack.push(Math.min(val, minStack.peek()));
    }
}

void pop() {
    if (!stack.isEmpty()) {
        stack.pop();
        minStack.pop();
    }
}

int getMin() {
